def stringConversion(X, Y):
    # Check if X and Y are both either all lowercase or all uppercase
    if not (all(c.islower() for c in X) or all(c.isupper() for c in X)):
        return 0
    if not (all(c.islower() for c in Y) or all(c.isupper() for c in Y)):
        return 0

    # Initialize a DP table where dp[i][j] will be True if X[:i] can be converted to Y[:j]
    dp = [[False] * (len(Y) + 1) for _ in range(len(X) + 1)]
    dp[0][0] = True  # Both strings are empty

    # Fill the DP table
    for i in range(1, len(X) + 1):
        for j in range(1, len(Y) + 1):
            if X[i - 1].isupper():
                if X[i - 1] == Y[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1]
            else:
                # If the character in X is lowercase, we have two choices:
                # 1. Convert it to uppercase and match it with Y[j-1]
                # 2. Skip the character in X
                if X[i - 1].upper() == Y[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1] or dp[i - 1][j]
                else:
                    dp[i][j] = dp[i - 1][j]

    return 1 if dp[len(X)][len(Y)] else 0

# Example usage:
# print(stringConversion("daBcd", "ABC"))  # Output: 1
# print(stringConversion("ABcd", "BCD"))   # Output: 0
